/**
 * AI KSHETRA 2026 - Main Certificate Retrieval Portal Controller
 * NEXAA - Next Gen Engineers & AI Association
 * R.V.R. & J.C. College of Engineering, Guntur
 *
 * Multi-Certificate Flow:
 * 1. User enters their phone number.
 * 2. Phone is SHA-256 hashed client-side; hash is looked up against participants.json.
 * 3. ALL matching certificates are returned (one per event attended).
 * 4. Each certificate is shown as a card with a direct PDF download button.
 * 5. No in-browser rendering; PDFs are pre-generated by the Python script.
 */

(function (window) {
  'use strict';

  function initPortal() {
    const inputPhone = document.getElementById('inputPhoneNumber');
    const btnLookup = document.getElementById('btnLookupParticipant');
    const statusPrompt = document.getElementById('terminalStatusPrompt');
    const resultPanel = document.getElementById('portalResultPanel');

    if (!btnLookup) return;

    btnLookup.addEventListener('click', handleLookup);

    if (inputPhone) {
      inputPhone.addEventListener('keydown', (e) => {
        if (e.key === 'Enter') handleLookup();
      });
      inputPhone.addEventListener('input', () => {
        if (resultPanel && resultPanel.style.display !== 'none') {
          resultPanel.style.display = 'none';
        }
      });
    }

    async function handleLookup() {
      const raw = inputPhone ? inputPhone.value.trim() : '';

      if (!raw) {
        showError("EMPTY_INPUT", "Please enter your 10-digit registered Indian mobile number.");
        return;
      }

      setStatus('&gt; VERIFYING PARTICIPANT CREDENTIALS...<br>&gt; COMPUTING SHA-256 HASH &amp; QUERYING INDEX...');
      btnLookup.disabled = true;
      btnLookup.innerHTML = '[ VERIFYING... ]';

      try {
        const res = await window.AI_AUTH.verifyParticipantByPhone(raw);

        // PRIVACY: Wipe input immediately after lookup
        if (inputPhone) inputPhone.value = '';

        if (res.success && res.certificates && res.certificates.length > 0) {
          showSuccess(res.certificates);
        } else {
          showError(res.code || "PARTICIPANT_NOT_FOUND", res.error || "No participant was found with the supplied registered phone number.");
        }
      } catch (err) {
        showError("SYSTEM_ERROR", err.message || "An unexpected error occurred during database lookup.");
      } finally {
        btnLookup.disabled = false;
        btnLookup.innerHTML = '[ VERIFY PARTICIPANT -&gt; ]';
      }
    }

    function setStatus(html) {
      if (statusPrompt) statusPrompt.innerHTML = html;
    }

    /**
     * Renders the success panel showing all certificates for this participant.
     * @param {object[]} certs - Array of sanitized certificate records
     */
    function showSuccess(certs) {
      const count = certs.length;
      const firstName = certs[0].name;

      setStatus(
        '&gt; ACCESS_GRANTED<br>&gt; ' + count + ' CERTIFICATE(S) FOUND FOR: ' + firstName
      );

      if (!resultPanel) return;

      // Build certificate cards HTML
      const cardsHtml = certs.map((c, idx) => {
        const badgeClass = c.certificateType && c.certificateType.toLowerCase().includes('merit')
          ? 'merit-badge'
          : 'participation-badge';

        return `
          <div class="cert-result-card" id="certCard_${idx}">
            <div class="cert-card-header">
              <div class="cert-card-event-tag">EVENT_${String(idx + 1).padStart(3, '0')}</div>
              <div class="cert-card-type-badge ${badgeClass}">${escHtml(c.certificateType)}</div>
            </div>
            <div class="cert-card-name">${escHtml(c.name)}</div>
            <div class="terminal-kv-grid cert-card-meta">
              <div class="kv-row">
                <span class="kv-key">CERTIFICATE ID:</span>
                <span class="kv-val highlight-val">${escHtml(c.certificateId)}</span>
              </div>
              <div class="kv-row">
                <span class="kv-key">EVENT:</span>
                <span class="kv-val">${escHtml(c.event)}</span>
              </div>
              <div class="kv-row">
                <span class="kv-key">TRACK:</span>
                <span class="kv-val">${escHtml(c.eventTrack || 'AI Kshetra 2026')}</span>
              </div>
              <div class="kv-row">
                <span class="kv-key">INSTITUTION:</span>
                <span class="kv-val">${escHtml(c.college)}</span>
              </div>
              <div class="kv-row">
                <span class="kv-key">DATE:</span>
                <span class="kv-val">${escHtml(c.date)}</span>
              </div>
            </div>
            <div class="cert-card-actions">
              <button
                type="button"
                class="btn btn-primary cert-dl-btn"
                data-certid="${escHtml(c.certificateId)}"
                id="btnDl_${idx}"
              >
                [ &darr; DOWNLOAD PDF ]
              </button>
              <a
                href="${window.AI_CONFIG.resolvePortalUrl('verify/?id=' + encodeURIComponent(c.certificateId))}"
                class="btn btn-outline"
                target="_blank"
                rel="noopener"
              >
                [ VERIFY &#8599; ]
              </a>
            </div>
          </div>
        `;
      }).join('');

      resultPanel.className = "terminal-card portal-result-card status-success";
      resultPanel.style.display = "block";
      resultPanel.innerHTML = `
        <div class="corner-marker corner-tl">+</div>
        <div class="corner-marker corner-tr">+</div>
        <div class="corner-marker corner-bl">+</div>
        <div class="corner-marker corner-br">+</div>

        <div class="terminal-tag">// 02 / AUTHENTICATION_SUCCESS</div>
        <h2 class="section-title">&gt;_ ACCESS_GRANTED</h2>

        <div class="status-badge authentic-badge">
          <span class="icon">[&checkmark;]</span>
          ${count} CERTIFICATE${count !== 1 ? 'S' : ''} FOUND &bull; ${escHtml(firstName)}
        </div>

        <p class="section-intro" style="margin: 1rem 0;">
          Your certificate${count !== 1 ? 's are' : ' is'} ready for download. Each PDF was generated and digitally signed by the NEXAA team.
        </p>

        ${count > 1 ? `
        <div style="margin: 1rem 0 1.25rem 0;">
          <button type="button" class="btn btn-primary" id="btnDlAll">
            [ &darr; DOWNLOAD ALL (${count}) CERTIFICATES ]
          </button>
        </div>` : ''}

        <div class="cert-results-grid">
          ${cardsHtml}
        </div>
      `;

      // Wire bulk download button if multiple certificates
      if (count > 1) {
        const btnAll = document.getElementById('btnDlAll');
        if (btnAll) {
          btnAll.addEventListener('click', async () => {
            btnAll.disabled = true;
            const originalText = btnAll.innerHTML;
            btnAll.innerHTML = '[ DOWNLOADING ALL... ]';
            for (let i = 0; i < certs.length; i++) {
              await window.AI_CERT.downloadPdf(certs[i].certificateId);
              await new Promise(r => setTimeout(r, 600));
            }
            btnAll.innerHTML = '[ &checkmark; ALL DOWNLOADED ]';
            setTimeout(() => {
              btnAll.disabled = false;
              btnAll.innerHTML = originalText;
            }, 3000);
          });
        }
      }

      // Wire up each download button
      certs.forEach((c, idx) => {
        const btn = document.getElementById('btnDl_' + idx);
        if (btn) {
          btn.addEventListener('click', () => {
            window.AI_CERT.downloadPdf(c.certificateId, btn);
          });
        }
      });

      resultPanel.scrollIntoView({ behavior: 'smooth', block: 'start' });
    }

    function showError(code, msg) {
      setStatus('&gt; ERROR: AUTHENTICATION_FAILED [' + code + ']');

      if (!resultPanel) return;

      resultPanel.className = "terminal-card portal-result-card status-failed";
      resultPanel.style.display = "block";
      resultPanel.innerHTML = `
        <div class="corner-marker corner-tl">+</div>
        <div class="corner-marker corner-tr">+</div>
        <div class="corner-marker corner-bl">+</div>
        <div class="corner-marker corner-br">+</div>

        <div class="terminal-tag">// ERROR_CODE: ${escHtml(code)}</div>
        <h2 class="section-title">&gt;_ ACCESS_DENIED</h2>

        <div class="status-badge invalid-badge">
          <span class="icon">[&cross;]</span> PARTICIPANT NOT FOUND
        </div>

        <p class="error-desc">${escHtml(msg)}</p>

        <div class="info-note" style="margin-top: 1rem;">
          <span class="note-prefix">// TROUBLESHOOTING_TIPS:</span>
          <ul>
            <li>Enter the exact 10-digit Indian mobile number provided during event registration.</li>
            <li>Prefixes like +91 or leading 0 are automatically accepted and normalised.</li>
            <li>If you attended with a team, ensure you enter your registered number.</li>
            <li>Contact NEXAA event support desk if your number is not registered.</li>
          </ul>
        </div>

        <div class="action-row" style="margin-top: 1.5rem;">
          <button type="button" class="btn btn-outline" onclick="document.getElementById('inputPhoneNumber').focus();">
            [ TRY AGAIN ]
          </button>
        </div>
      `;
    }

    /** Minimal HTML escape to prevent XSS in dynamically built innerHTML */
    function escHtml(str) {
      if (!str) return '';
      return String(str)
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;');
    }
  }

  document.addEventListener('DOMContentLoaded', initPortal);
})(window);